namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public required string DepartmentCode { get; set; }
    public bool IsFeatured { get; set; }
}

namespace CourseCatalog.Models;

public class Department
{
    public required string Code { get; set; }
    public required string Name { get; set; }
    public required string Description { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6–12 alphanumeric characters.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    public int? CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(string code);
    IReadOnlyList<Course> GetCourses(string? searchTerm = null, string? departmentCode = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class InMemoryCatalogService : ICatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
        new() { Code = "PHYS", Name = "Physics", Description = "Fundamental laws of nature, from quantum mechanics to cosmology." },
        new() { Code = "ENG", Name = "English", Description = "Literature, writing, and critical analysis of texts." },
        new() { Code = "HIST", Name = "History", Description = "Study of past events, civilizations, and historical analysis." },
    ];

    private readonly List<Course> _courses =
    [
        new()
        {
            Id = 1, Code = "CS 101", Title = "Introduction to Programming",
            Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentCode = "CS", IsFeatured = true,
            InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen specializes in programming languages and computer science education. She has over 15 years of teaching experience and has authored two introductory textbooks."
        },
        new()
        {
            Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms",
            Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).",
            Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", DepartmentCode = "CS", IsFeatured = true,
            InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez is a researcher in algorithm optimization with publications in top-tier journals. He brings real-world industry experience from a decade at a major tech company."
        },
        new()
        {
            Id = 3, Code = "CS 310", Title = "Database Systems",
            Description = "Relational database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentCode = "CS", IsFeatured = false,
            InstructorName = "Prof. Carol Nguyen", InstructorBio = "Prof. Nguyen has extensive experience in database architecture and has consulted for several Fortune 500 companies on data management strategies."
        },
        new()
        {
            Id = 4, Code = "MATH 101", Title = "Calculus I",
            Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.",
            Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentCode = "MATH", IsFeatured = true,
            InstructorName = "Dr. David Park", InstructorBio = "Dr. Park is an award-winning educator recognized for making calculus accessible and engaging. His research focuses on differential equations."
        },
        new()
        {
            Id = 5, Code = "MATH 220", Title = "Linear Algebra",
            Description = "Vector spaces, matrices, eigenvalues, and linear transformations with applications to data science and engineering.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentCode = "MATH", IsFeatured = false,
            InstructorName = "Dr. Elena Rossi", InstructorBio = "Dr. Rossi is a mathematician specializing in applied linear algebra and numerical methods. She has published over 30 research papers."
        },
        new()
        {
            Id = 6, Code = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:00 PM", DepartmentCode = "PHYS", IsFeatured = true,
            InstructorName = "Dr. Frank Wilson", InstructorBio = "Dr. Wilson is an experimental physicist whose research focuses on condensed matter physics. He is passionate about hands-on laboratory education."
        },
        new()
        {
            Id = 7, Code = "PHYS 250", Title = "Modern Physics",
            Description = "Special relativity, quantum mechanics, atomic structure, and nuclear physics.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentCode = "PHYS", IsFeatured = false,
            InstructorName = "Dr. Grace Kim", InstructorBio = "Dr. Kim is a theoretical physicist with a focus on quantum information science. She has received multiple grants for her research."
        },
        new()
        {
            Id = 8, Code = "ENG 110", Title = "College Writing",
            Description = "Develop academic writing skills through essay composition, argumentation, and critical reading of diverse texts.",
            Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentCode = "ENG", IsFeatured = false,
            InstructorName = "Prof. Hannah Lee", InstructorBio = "Prof. Lee is a published author and writing instructor with expertise in rhetoric and composition pedagogy."
        },
        new()
        {
            Id = 9, Code = "ENG 230", Title = "American Literature",
            Description = "Survey of American literature from the colonial period to the present, examining major authors and literary movements.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", DepartmentCode = "ENG", IsFeatured = false,
            InstructorName = "Dr. Ian Brooks", InstructorBio = "Dr. Brooks is a literary scholar specializing in 20th-century American fiction. He has published extensively on the works of Faulkner and Morrison."
        },
        new()
        {
            Id = 10, Code = "HIST 101", Title = "World History to 1500",
            Description = "Survey of world civilizations from prehistory through the late medieval period, examining political, social, and cultural developments.",
            Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentCode = "HIST", IsFeatured = false,
            InstructorName = "Dr. Julia Adams", InstructorBio = "Dr. Adams is a historian specializing in ancient and medieval civilizations. She has led archaeological fieldwork in the Mediterranean region."
        },
    ];

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetCourses(string? searchTerm = null, string? departmentCode = null)
    {
        IEnumerable<Course> results = _courses;

        if (!string.IsNullOrWhiteSpace(departmentCode))
            results = results.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            results = results.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return results.OrderBy(c => c.Code).ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) =>
        _courses.FirstOrDefault(c => c.Id == id);
}

